\title{Homological Necessity for an Extremal Spectral-Radius Bound:\\
The Cone Mechanism and Its Reduced-Euler Shadow}
\author{Aristotle}
\date{2026-06-24}

\begin{document}
\maketitle

\begin{abstract}
We study the rigidity phenomenon underlying an extremal eigenvalue bound for
finite abstract simplicial complexes. For a pure $r$-dimensional complex $K$ on
$n$ vertices, a spectral-radius bound of the form
$q_{r-1}(K) \le t\,n - (t-1)(r+1)$
governs a designated eigenvalue $q_{r-1}$ of a higher-dimensional up--down
Laplacian. The central rigidity statement asserts that \emph{saturation} of this
bound forces a strong local-topological consequence: the link of every
$(r-t)$-dimensional face must be acyclic, so that its reduced homology
$\rH_t(\lk_K(\sigma);\RR)$ vanishes. The structural witness of this acyclicity
is that the relevant links become \textbf{cones}. This paper isolates and
rigorously establishes the \emph{necessary numerical shadow} of that statement.
We develop a compact framework for finite abstract simplicial complexes, their
links, and the reduced Euler characteristic $\rEuler$, and we prove that any
cone with a fresh apex has vanishing reduced Euler characteristic, via a
sign-reversing involution that pairs apex-free and apex-containing faces. Since
trivial reduced homology forces $\rEuler = 0$, our theorem captures exactly the
checkable invariant that acyclicity must leave behind; we are scrupulous that
$\rEuler = 0$ is \emph{necessary but not sufficient} for acyclicity.
\end{abstract}

\textbf{Keywords:} abstract simplicial complex, reduced Euler characteristic,
link, cone, acyclicity, spectral radius bound, reduced homology,
sign-reversing involution, up--down Laplacian.

\section{Introduction}

\subsection{Motivation}
Spectral methods translate combinatorial and topological questions about a
structure into questions about the eigenvalues of an associated operator. For
graphs, the Laplacian spectrum encodes connectivity, expansion, mixing rates,
and bisection width. For simplicial complexes one works with families of
\emph{up--down Laplacians} acting on chains in each dimension, and a rich theory
(Garland's method, high-dimensional expanders, the local-to-global paradigm)
relates global spectral data to the geometry of \textbf{links}, the local
neighborhoods of faces.

A recurring theme is \textbf{extremal rigidity}: an inequality relating a
spectral quantity to combinatorial parameters is often \emph{sharp}, and the
complexes achieving equality are severely constrained. Sharpness converts an
inequality into a structural classification.

For a pure $r$-dimensional complex $K$ on $n$ vertices, the eigenvalue
$q_{r-1}(K)$ of an up--down Laplacian satisfies
\begin{equation}\label{eq:bound}
q_{r-1}(K) \;\le\; t\,n - (t-1)(r+1),
\end{equation}
for a codimension parameter $t$. The right-hand side factors as
\begin{equation}\label{eq:factor}
t\,n - (t-1)(r+1) \;=\; (t-1)(n-r-1) + n,
\end{equation}
making transparent that the bound interpolates linearly in $n$ and that the
codimension $t$ scales the excess dimension $n-r-1$.

\begin{quote}
\textbf{Necessity Principle.} If $K$ saturates \eqref{eq:bound}, i.e.
$q_{r-1}(K) = t\,n - (t-1)(r+1)$, then for every $(r-t)$-dimensional face
$\sigma$, the link $\lk_K(\sigma)$ is acyclic; in particular
$\rH_t(\lk_K(\sigma);\RR) = 0$.
\end{quote}

The structural mechanism is that saturation forces these links to be
\textbf{cones} --- they acquire an apex vertex joined to every face --- and
cones are contractible, hence acyclic.

\subsection{Contribution and logical scope}
We build a minimal, reusable framework for finite abstract simplicial complexes,
their links, and the reduced Euler characteristic, and we prove the
\emph{necessary numerical shadow} of the Necessity Principle: a cone over any
finite complex, formed with a fresh apex, has reduced Euler characteristic $0$.
Since acyclicity (vanishing of all reduced Betti numbers) implies the vanishing
of their alternating sum, and since the relevant links are cones under
saturation, this is exactly the necessary consequence expressible at the level
of the Euler characteristic. We emphasize:
\[
\rEuler = -\rb_0 + \rb_1 - \rb_2 + \cdots, \qquad \rb_i := \dim_{\RR}\rH_i,
\]
so $\rEuler = 0$ is necessary but \textbf{not} sufficient for acyclicity:
distinct Betti numbers can cancel. We present our theorem honestly as the
numerical shadow of trivial reduced homology.

\section{Preliminaries: finite abstract simplicial complexes}
Throughout, $V$ is a vertex type with decidable equality, and all face
collections are finite.

\begin{definition}[Abstract simplicial complex]\label{def:asc}
A \emph{finite abstract simplicial complex} over $V$ is a finite family $K$ of
finite subsets of $V$ (its \emph{faces}) such that
(1) $\varnothing \in K$, and
(2) if $F \in K$ and $G \subseteq F$ then $G \in K$.
A face $F$ has \emph{dimension} $\dim F = |F| - 1$. The complex is \emph{pure of
dimension $r$} if every maximal face has dimension $r$, and lives on $n$
vertices.
\end{definition}

\begin{definition}[Reduced Euler characteristic]\label{def:euler}
The \emph{reduced Euler characteristic} of $K$ is
\begin{equation}\label{eq:euler}
\rEuler(K) \;=\; \sum_{F \in K} (-1)^{\dim F} \;=\; \sum_{F \in K} (-1)^{|F|+1}
\;\in\; \ZZ,
\end{equation}
the sum taken over all faces including $\varnothing$ (contributing $-1$). Thus
$\rEuler = \chi - 1$.
\end{definition}

\begin{definition}[Link]\label{def:link}
For a face $\sigma \in K$, the \emph{link} of $\sigma$ is
\begin{equation}\label{eq:link}
\lk_K(\sigma) \;=\; \{\, F \in K : F \cap \sigma = \varnothing,\ F \cup \sigma \in K \,\}.
\end{equation}
\end{definition}

\begin{proposition}[The link is a complex]\label{prop:link-complex}
For $\sigma \in K$, $\lk_K(\sigma)$ is a finite abstract simplicial complex.
\end{proposition}
\begin{proof}[Proof sketch]
\textbf{Empty face:} $\varnothing$ is disjoint from $\sigma$ and
$\varnothing \cup \sigma = \sigma \in K$ --- here membership $\sigma \in K$ is
essential. \textbf{Downward closure:} if $F \in \lk_K(\sigma)$ and $G \subseteq F$
then $G \in K$; $G$ is disjoint from $\sigma$ (disjointness is monotone); and
$G \cup \sigma \subseteq F \cup \sigma \in K$, so $G \cup \sigma \in K$. Hence
$G \in \lk_K(\sigma)$.
\end{proof}

\begin{proposition}[Link codimension]\label{prop:codim}
If $K$ is pure of dimension $r$ and $\sigma$ is an $(r-t)$-face, then
$\lk_K(\sigma)$ is pure of dimension $t-1$.
\end{proposition}
\begin{proof}[Proof sketch]
A facet $F \supseteq \sigma$ has $|F| = r+1$; removing the $r-t+1$ vertices of
$\sigma$ leaves $F \setminus \sigma$ with $t$ vertices, i.e. dimension $t-1$.
Maximality transfers between $K$ and the link.
\end{proof}

\section{The cone construction}

\begin{definition}[Cone]\label{def:cone}
For $v \in V$ and a complex $K$, the \emph{cone} over $K$ with apex $v$ is
\begin{equation}\label{eq:cone}
\cone_v(K) \;=\; K \;\cup\; \{\, F \cup \{v\} : F \in K \,\},
\end{equation}
the \emph{apex-free} faces $K$ together with the \emph{apex-containing}
enlargements.
\end{definition}

\begin{proposition}[The cone is a complex]\label{prop:cone-complex}
$\cone_v(K)$ is a finite abstract simplicial complex, for any $v$.
\end{proposition}
\begin{proof}[Proof sketch]
$\varnothing \in K \subseteq \cone_v(K)$. For downward closure, let
$F \in \cone_v(K)$ and $G \subseteq F$. If $F \in K$ then $G \in K$. If
$F = F_0 \cup \{v\}$ with $F_0 \in K$: when $v \in G$, the residual
$G \setminus \{v\} \subseteq F_0$ lies in $K$ so $G$ is apex-containing; when
$v \notin G$, then $G \subseteq F_0 \in K$ is apex-free. Either way
$G \in \cone_v(K)$.
\end{proof}

\begin{definition}[Fresh apex]\label{def:fresh}
The apex $v$ is \emph{fresh} for $K$ if $v \notin F$ for all $F \in K$.
\end{definition}

\begin{proposition}[Disjointness of the strata]\label{prop:disjoint}
If $v$ is fresh for $K$, then the apex-free faces $K$ and the apex-containing
faces $\{F \cup \{v\} : F \in K\}$ are disjoint.
\end{proposition}
\begin{proof}[Proof sketch]
Any apex-containing face contains $v$; if it were also apex-free, $v$ would lie
in a face of $K$, contradicting freshness.
\end{proof}

\section{Main theorem}

\begin{theorem}[Reduced Euler characteristic of a cone]\label{thm:main}
Let $K$ be a finite abstract simplicial complex and $v$ a \emph{fresh} apex for
$K$. Then
\begin{equation}\label{eq:main}
\rEuler\big(\cone_v(K)\big) = 0.
\end{equation}
\end{theorem}
\begin{proof}
By Proposition~\ref{prop:disjoint} the faces of $\cone_v(K)$ partition into the
disjoint union of the apex-free faces $K$ and the apex-containing faces
$\{F \cup \{v\}: F \in K\}$. Splitting \eqref{eq:euler},
\[
\rEuler(\cone_v(K)) = \sum_{F\in K}(-1)^{|F|+1}
\;+\; \sum_{F' \text{ apex-containing}} (-1)^{|F'|+1}.
\]
The map $F \mapsto F\cup\{v\}$ is a bijection from $K$ onto the apex-containing
faces (injective since $v$ is fresh, as ``erase $v$'' recovers $F$), so we
reindex over $F \in K$. Freshness gives $|F\cup\{v\}| = |F|+1$, hence
\[
(-1)^{|F\cup\{v\}|+1} = (-1)^{|F|+2} = -\,(-1)^{|F|+1}.
\]
Therefore the second sum is the negative of the first and they cancel termwise,
giving $\rEuler(\cone_v(K)) = 0$.
\end{proof}

\begin{remark}[A sign-reversing involution]\label{rem:involution}
Theorem~\ref{thm:main} is a sign-reversing involution. The toggle
$\iota: F \mapsto F \mathbin{\triangle} \{v\}$ is a fixed-point-free involution
on the faces of the cone that flips $(-1)^{|F|+1}$ by changing $|F|$ by $\pm 1$,
forcing the signed count to vanish. Disjointness of the strata, injectivity of
$F \mapsto F \cup \{v\}$, and the unit cardinality shift are all consequences of
freshness, which is therefore load-bearing.
\end{remark}

\begin{corollary}[Apex complexes]\label{cor:apex}
If a complex $L$ has an apex $w$ (a vertex with $F \cup \{w\} \in L$ whenever
$F \in L$), then $\rEuler(L) = 0$.
\end{corollary}
\begin{proof}[Proof sketch]
An apex $w$ realizes $L$ as a cone over its apex-free subcomplex
$L_0 = \{F \in L : w \notin F\}$, with $w$ fresh for $L_0$; apply
Theorem~\ref{thm:main}.
\end{proof}

\section{From the shadow to the Necessity Principle}

\subsection{The spectral bound}
Let $K$ be pure of dimension $r$ on $n$ vertices, and set the bound function
$q_{\mathrm{bd}}(n,r,t) := t\,n - (t-1)(r+1)$. Two identities organize it:
\begin{itemize}[nosep]
\item \emph{Factorization:} $q_{\mathrm{bd}}(n,r,t) = (t-1)(n-r-1) + n$.
\item \emph{Discrete derivatives:}
$q_{\mathrm{bd}}(n+1,r,t) - q_{\mathrm{bd}}(n,r,t) = t$ and
$q_{\mathrm{bd}}(n,r+1,t) - q_{\mathrm{bd}}(n,r,t) = -(t-1)$.
\end{itemize}

\subsection{The logical chain}
The Necessity Principle composes three implications:
\[
\underbrace{q_{r-1}(K) = q_{\mathrm{bd}}(n,r,t)}_{\text{saturation}}
\;\Rightarrow\;
\underbrace{\lk_K(\sigma)\text{ is a cone}}_{\text{rigidity}}
\;\Rightarrow\;
\underbrace{\rH_t(\lk_K(\sigma);\RR)=0}_{\text{acyclicity}}.
\]
The last implication is topology (cones are contractible); its necessary
numerical shadow is that the reduced Euler characteristic of each such link
vanishes, which is Theorem~\ref{thm:main}.

\begin{theorem}[Necessary numerical shadow]\label{thm:shadow}
If $K$ is pure of dimension $r$ on $n$ vertices, $\sigma$ is an $(r-t)$-face,
and saturation forces $\lk_K(\sigma) = \cone_v(L)$ for some complex $L$ and
fresh apex $v$, then $\rEuler(\lk_K(\sigma)) = 0$.
\end{theorem}
\begin{proof}
Immediate from Theorem~\ref{thm:main} applied to $L$ and $v$.
\end{proof}

\section{Algorithms}
We summarize the reference algorithms (full Python implementations accompany
this paper).

\paragraph{A. Downward closure.} From generating facets, enumerate all subsets
to build the closed face set including $\varnothing$. Complexity
$O(\sum_i 2^{|F_i|})$.

\paragraph{B. Reduced Euler characteristic.} Sum $(-1)^{|F|+1}$ over all faces;
complexity $O(|K|)$.

\paragraph{C. Cone construction and certificate.} Verify freshness, form the two
strata, verify disjointness (Prop.~\ref{prop:disjoint}), and verify
$\rEuler = 0$ (Thm.~\ref{thm:main}); complexity $O(|K|)$.

\paragraph{D. Link extraction.} Collect faces $F$ with $F \cap \sigma = \varnothing$
and $F \cup \sigma \in K$; complexity $O(|K| \cdot c)$.

\paragraph{E. Involution verifier.} Confirm the toggle
$\iota(F) = F \triangle \{v\}$ is a fixed-point-free, sign-reversing involution
on the cone, witnessing $\rEuler = 0$ without summation; complexity $O(|C|)$.

\section{Discussion and future directions}

\subsection{Honest logical status}
We proved the reduced-Euler shadow: cones have $\rEuler = 0$. Since acyclicity
implies $\rEuler = 0$ but not conversely, the result is \textbf{necessary, not
sufficient} for acyclicity; this transparency separates the verified
combinatorial core from the deeper claims.

\subsection{Future research program}

\begin{conjecture}[C1: Full homological necessity]
If a pure $r$-complex $K$ saturates $q_{r-1}(K) = tn - (t-1)(r+1)$, then
$\rH_i(\lk_K \sigma;\RR) = 0$ for all $i$ and every $(r-t)$-face $\sigma$, not
merely $\rEuler = 0$. Saturation is a rank condition on the up--down Laplacian,
and rank deficiency localizes to links as exactness of the simplicial boundary;
adding a chain complex over $\RR$ with a cone contraction
$\partial s + s\partial = \mathrm{id}$ upgrades $\rEuler = 0$ to $\rH = 0$.
\end{conjecture}

\begin{conjecture}[C2: Apex detection is the obstruction]
A finite complex has $\rEuler = 0$ \emph{robustly} (for it and every induced
subcomplex on a vertex subset) iff it admits an apex on each such subset. The
only parity-stable, locally checkable certificate of $\rEuler = 0$ is the toggle
$F \mapsto F \triangle \{w\}$, which exists exactly when $w$ is an apex; one
direction is Corollary~\ref{cor:apex}, the converse a finite search.
\end{conjecture}

\begin{conjecture}[C3: Sharpness of the codimension $t$]
Under saturation, the first non-vanishing reduced homology of a link occurs in
degree exactly $t-1$, and $t$ is the smallest shift for which necessity holds.
Since the link of an $(r-t)$-face has dimension $t-1$
(Prop.~\ref{prop:codim}), degree $t$ is the boundary degree where homology can
first be forced to die.
\end{conjecture}

\begin{conjecture}[C4: Quantitative defect $\Rightarrow$ Betti bound]
If $q_{r-1}(K) = tn - (t-1)(r+1) - \delta$ with defect $\delta > 0$, then
$\sum_\sigma \dim \rH_t(\lk_K \sigma;\RR) \le c(r,t)\,\delta$ for an explicit
$c(r,t)$. The eigenvalue gap is a continuous proxy for total homological mass;
the discrete derivatives of $q_{\mathrm{bd}}$ seed the estimate.
\end{conjecture}

\subsection{Applications}
\begin{itemize}[nosep]
\item \textbf{Spectral certificates for topology:} a maximal spectral reading
certifies local acyclicity at the cost of an eigenvalue computation.
\item \textbf{High-dimensional expanders:} local-to-global theorems hinge on
link structure; the cone mechanism is a pure instance.
\item \textbf{Discretized physics:} extremal spectra of Laplace-type operators
signal degenerate, cone-like local configurations.
\end{itemize}

\section{Conclusion}
The reduced Euler characteristic of a cone with a fresh apex vanishes
(Theorem~\ref{thm:main}), proved by a sign-reversing involution powered by apex
freshness. Together with the facts that cones and links are genuine complexes
(Propositions~\ref{prop:link-complex},~\ref{prop:cone-complex}), that the cone
strata are disjoint (Proposition~\ref{prop:disjoint}), and that link
codimension is $t-1$ (Proposition~\ref{prop:codim}), this establishes the
necessary numerical shadow of the statement that saturating
$q_{r-1}(K) = tn - (t-1)(r+1)$ forces the links of $(r-t)$-faces to be acyclic.
Four future directions chart the route to the full homological theorem.

