function InvolutionCertificate(C, v):
    for F in C:
        G <- F XOR {v}
        if G not in C: return False           # iota maps C to C
        if (F XOR {v}) XOR {v} != F: return False   # involution
        if (-1)^(|G|+1) != -(-1)^(|F|+1): return False  # sign reversal
    return True
